import unittest

from warehouse import (
    occupied,
    free_space,
    fits,
    fit_order,
    fit_orders,
)


class WarehouseTests(unittest.TestCase):
    def test_occupied_sums_all_three(self):
        self.assertEqual(occupied(3, 4, 5), 12)

    def test_occupied_zero_allowed(self):
        self.assertEqual(occupied(0, 0, 0), 0)

    def test_occupied_negative_raises(self):
        for args in [(-1, 0, 0), (0, -1, 0), (0, 0, -1)]:
            with self.assertRaises(ValueError):
                occupied(*args)

    def test_free_space_basic(self):
        self.assertEqual(free_space(100, 30, 20, 10), 40)

    def test_free_space_never_negative(self):
        self.assertEqual(free_space(10, 30, 20, 10), 0)

    def test_free_space_negative_capacity_raises(self):
        with self.assertRaises(ValueError):
            free_space(-1, 0, 0, 0)

    def test_fits_boundary_equal(self):
        self.assertTrue(fits(40, 100, 30, 20, 10))

    def test_fits_over_by_one(self):
        self.assertFalse(fits(41, 100, 30, 20, 10))

    def test_fits_zero(self):
        self.assertTrue(fits(0, 0, 0, 0, 0))

    def test_fits_negative_qty_raises(self):
        with self.assertRaises(ValueError):
            fits(-1, 100, 0, 0, 0)

    def test_fit_order_cut(self):
        self.assertEqual(fit_order(50, 100, 30, 20, 10), (40, 10))

    def test_fit_order_fits_fully(self):
        self.assertEqual(fit_order(10, 100, 30, 20, 10), (10, 0))

    def test_fit_order_no_space(self):
        self.assertEqual(fit_order(5, 10, 10, 0, 0), (0, 5))

    def test_fit_order_negative_raises(self):
        with self.assertRaises(ValueError):
            fit_order(-1, 100, 0, 0, 0)

    def test_fit_orders_sequential(self):
        self.assertEqual(fit_orders([30, 30, 30], 100, 0, 0, 0), [30, 30, 30])

    def test_fit_orders_limited(self):
        self.assertEqual(fit_orders([30, 30, 30], 50, 0, 0, 0), [30, 20, 0])

    def test_fit_orders_preserves_input(self):
        orders = [10, 20, 30]
        fit_orders(orders, 100, 0, 0, 0)
        self.assertEqual(orders, [10, 20, 30])

    def test_fit_orders_empty(self):
        self.assertEqual(fit_orders([], 100, 0, 0, 0), [])

    def test_fit_orders_length_matches(self):
        result = fit_orders([5, 5, 5, 5], 12, 0, 0, 0)
        self.assertEqual(len(result), 4)
        self.assertEqual(result, [5, 5, 2, 0])


if __name__ == "__main__":
    unittest.main()
```

```python
import unittest

from warehouse import occupied, free_space, fits, fit_order, fit_orders


class ExtraWarehouseTests(unittest.TestCase):
    def test_occupied_does_not_mutate_and_order_independent(self):
        self.assertEqual(occupied(1, 2, 3), occupied(3, 2, 1))

    def test_free_space_negative_raw_finished_transit_raise(self):
        for args in [(10, -1, 0, 0), (10, 0, -1, 0), (10, 0, 0, -1)]:
            with self.assertRaises(ValueError):
                free_space(*args)

    def test_free_space_exact_zero_boundary(self):
        self.assertEqual(free_space(60, 30, 20, 10), 0)

    def test_fits_negative_capacity_raises(self):
        with self.assertRaises(ValueError):
            fits(0, -1, 0, 0, 0)

    def test_fits_negative_occupied_arg_raises(self):
        with self.assertRaises(ValueError):
            fits(0, 10, -1, 0, 0)

    def test_fits_when_overfull_only_zero_fits(self):
        self.assertTrue(fits(0, 5, 10, 0, 0))
        self.assertFalse(fits(1, 5, 10, 0, 0))

    def test_fit_order_negative_capacity_raises(self):
        with self.assertRaises(ValueError):
            fit_order(0, -1, 0, 0, 0)

    def test_fit_order_zero_qty(self):
        self.assertEqual(fit_order(0, 100, 30, 20, 10), (0, 0))

    def test_fit_order_overfull_accepts_nothing(self):
        self.assertEqual(fit_order(7, 5, 10, 0, 0), (0, 7))

    def test_fit_orders_accumulates_in_transit(self):
        # 10 занято, capacity 25 -> свободно 15; 10 принято, затем 5, затем 0
        self.assertEqual(fit_orders([10, 10, 10], 25, 0, 0, 10), [10, 5, 0])

    def test_fit_orders_negative_order_raises(self):
        with self.assertRaises(ValueError):
            fit_orders([5, -1], 100, 0, 0, 0)

    def test_fit_orders_negative_capacity_raises(self):
        with self.assertRaises(ValueError):
            fit_orders([1], -1, 0, 0, 0)

    def test_fit_orders_zero_orders_kept(self):
        self.assertEqual(fit_orders([0, 0], 0, 0, 0, 0), [0, 0])

    def test_fit_orders_does_not_mutate_tuple_input(self):
        orders = (3, 4, 5)
        self.assertEqual(fit_orders(orders, 100, 0, 0, 0), [3, 4, 5])
        self.assertEqual(orders, (3, 4, 5))


if __name__ == "__main__":
    unittest.main()
